function studentTable(mode='directory'){
 const due=mode==='dues';
 return `<div class="desktop-table table-wrap"><table><thead><tr><th>Student</th><th>Class</th><th>${due?'Outstanding':'Information'}</th><th>${due?'Status':'Last updated'}</th><th>Action</th></tr></thead><tbody>${students.map((s,i)=>`<tr data-student="${s[0].toLowerCase()} ${s[1]}"><td><strong>${s[0]}</strong><small>SR ${s[1]}</small></td><td>${s[2]}</td><td>${due?s[4]:pill(i===1?'Phone missing':'Complete',i===1?'orange':'green')}</td><td>${due?pill(s[5],i===2?'green':'orange'):'16 Sep 2026'}</td><td><a class="text-link" href="${url(due?'payments':'student')}">${due?'Receive payment':'Open record'} ${icon('arrow')}</a></td></tr>`).join('')}</tbody></table></div><div class="mobile-cards">${students.map((s,i)=>`<article class="mobile-card" data-student="${s[0].toLowerCase()} ${s[1]}"><div class="mobile-card-head"><div><h3>${s[0]}</h3><p>SR ${s[1]} · ${s[2]}</p></div>${due?`<strong>${s[4]}</strong>`:`<span class="avatar">${s[3]}</span>`}</div><div class="mobile-card-foot">${pill(due?s[5]:i===1?'Phone missing':'Complete',i===1||due&&i!==2?'orange':'green')}<a class="text-link" href="${url(due?'payments':'student')}">${due?'Receive':'Open record'} ${icon('arrow')}</a></div></article>`).join('')}</div><div id="no-matches" class="empty" hidden>${icon('search')}<h3>No matching students</h3><p>Try a name or SR number, or clear your search.</p></div>`;
}
function studentsView(due=false){return title(due?'SCHOOL FEES':'STUDENT DIRECTORY',due?'Dues & follow-ups':role==='teacher'?'My class':'Find a student',due?'See what is outstanding and choose the right next action.':'Names, details and outstanding work in one place.',button('Export list','export','','download'))+
`<div class="toolbar"><div class="search-wrap">${field('student-search','Search students','<input class="search" id="student-search" type="search" placeholder="Name or SR number…">')}</div>${field('class-filter','Class',select('class-filter',['VI A']))}${field('session-filter','Session',select('session-filter',['2026–27']))}</div>`+
(due?metrics([['Total outstanding','₹8,500','4 students in this view','money'],['Overdue','₹7,000','2 families','clock'],['Due this week','₹1,500','1 family','calendar'],['Up to date','1','No outstanding fees','check']]):'')+
panel(due?'Outstanding balances':'Class VI A','4 example students · sample records',studentTable(due?'dues':'directory'))+
`<div style="height:20px"></div>`+note(due?'Preview before sending':'A reliable search',due?'A follow-up preview shows the selected families, balances and delivery status before messages are sent.':'SR numbers stay as text so leading zeros are retained. Search results keep the current class and session.')}

