function login(){return `<div class="prototype-only">Design preview · No real sign-in</div><div class="token-layout"><header class="token-header"><div class="school-name">Veer Patta Public School<small>VPPS One · The school workspace</small></div><span class="brand-mark" style="background:var(--nav)">${icon('book')}</span></header>${title('WELCOME BACK','Your school day starts here','Sign in with the account provided by your school.')}${panel('Sign in','Use your school account',body(`<form id="login-form"><div class="stack">${field('email','Email address','<input id="email" type="email" autocomplete="username" placeholder="name@school.example" required>')}${field('password','Password','<input id="password" type="password" autocomplete="current-password" required>')}<button class="button primary" type="submit">Continue to my workspace ${icon('arrow')}</button><p id="login-state" class="small" role="status"></p></div></form>`))}<div style="height:20px"></div>${note('Using a school-issued sign-in link?','Open the link sent by the office. If it has expired, ask the office for a new one.')}<p class="footer-note">Your account determines your workspace. Teachers start with their class; accounts staff start in School Fees; administrators start with the school overview.</p></div>`}
function staff(){return title('SCHOOL ADMINISTRATION','Staff & assignments','Keep every person connected to the right school work.',button('Add staff member','staff-preview','primary','plus'))+metrics([['Active staff','40','Current school accounts','users'],['Classes assigned','30 / 30','Each has a class teacher','check'],['Coordinators','2','Academic and examinations','book'],['Needs setup','1','A new teacher awaits assignment','clock']])+panel('Staff directory','Role and assignment are separate',row('users','Meera Joshi','Teacher · Class VI A · English',pill('Active','green'))+row('users','Kavita Rao','Office · Student services',pill('Active','green'))+row('users','Priya Shah','Exam coordinator · Assessments',pill('Active','green'))+row('users','New teacher','Teacher · No class assigned',button('Assign class','staff-preview','','plus')))+`<div style="height:20px"></div>`+note('Keep roles recognizable','An office role is not automatically an accountant. Financial app access and teaching assignments are resolved independently.')}
function setup(){return title('SCHOOL ADMINISTRATION','School settings','Academic structure and operational settings, grouped by purpose.')+cols(panel('Academic setup','Current session · 2026–27',row('calendar','Sessions & calendar','Term dates, school days and holidays',button('Manage','session-preview'))+row('users','Classes & sections','Classes, sections and enrolments',button('Manage','session-preview'))+row('book','Subjects & teaching assignments','Subjects, teachers and class links',button('Manage','staff-preview')))+panel('Information collection','SamPark setup',task('file','Fields & templates','The information teachers are asked to confirm','sampark')+task('message','Message delivery','Queued, sent and failed updates with retry history','states')),
panel('Operational settings','Visible to administrators',row('clock','Background jobs','Latest runs and failures',button('View status','jobs-preview'))+row('shield','Activity history','Who changed what and when',button('View activity','activity-preview')))+note('Preview the effect','Show affected classes and records before a school-wide change. Keep daily work out of the settings area.'))}
const renderers={accountant,teacher,'teacher-hi':teacher,admin,office,academic,exam,viewer,payments,dues:()=>studentsView(true),receipts,'fee-report':feeReport,students:()=>studentsView(false),student:studentView,attendance,requests,'request-link':requestLink,sampark,review,cover,timetable,marks,reports,documents,apps,settings,states,components,more,login,staff,setup};
function shell(content){const p=profiles[role], nav=navs[role],selected=screen==='teacher-hi'?'teacher':screen;
 const bottom=nav.length>4?[...nav.slice(0,4),['more','More','apps']]:nav;
 return `<aside class="sidebar"><a class="brand" href="index.html"><span class="brand-mark">${icon('book')}</span><span>VPPS <span style="font-weight:400">One</span><small>THE SCHOOL WORKSPACE</small></span></a><div class="nav-label">${p[1]}</div><nav aria-label="Main navigation">${nav.map(([id,label,ico])=>`<a class="side-link ${selected===id?'active':''}" ${selected===id?'aria-current="page"':''} href="${url(id)}">${icon(ico)}${label}${id==='requests'?'<span class="count">2</span>':''}</a>`).join('')}</nav><div class="nav-label">Personal</div><a class="side-link" href="${url('settings')}">${icon('settings')}Preferences</a><a class="side-link" href="index.html">${icon('apps')}Design atlas</a><div class="sidebar-foot"><strong>Veer Patta Public School</strong>Session 2026–27<br><span style="display:inline-block;margin-top:12px">Illustrative design · v1.0</span></div></aside><div class="frame"><header class="topbar"><div class="school-name">Veer Patta Public School<small>${hi?'सत्र 2026–27':'Session 2026–27'}</small></div><div class="top-actions"><span class="demo-tag">Design preview</span><a class="button ghost language" href="${url(role==='teacher'?(hi?'teacher':'teacher-hi'):'settings',role)}" lang="${hi?'en':'hi'}">${hi?'English':'हिंदी'}</a><button class="icon-button notification" aria-label="Notifications" data-action="notifications">${icon('bell')}</button><div class="profile"><span class="avatar">${p[2]}</span><span class="profile-label"><strong>${p[0]}</strong><small>${p[1]}</small></span></div></div></header><main id="main">${content}<p class="footer-note">DESIGN PREVIEW · Illustrative names, figures and dates · Actions simulate outcomes</p></main></div><nav class="bottom-nav" aria-label="Mobile navigation">${bottom.map(([id,label,ico])=>`<a href="${id==='gallery'?'index.html':url(id)}" class="${selected===id?'active':''}" ${selected===id?'aria-current="page"':''}>${icon(ico)}<span>${hi?({'My day':'आज','My class':'मेरी कक्षा','Requests':'अनुरोध','Timetable':'समय-सारणी'}[label]||label):({'Receive payment':'Receive','Dues & follow-ups':'Dues','School Fees':'Fees','Today’s overview':'Today','School summary':'Summary','School apps':'Apps','Office desk':'Home','Review changes':'Review','Class cover':'Cover'}[label]||label)}</span></a>`).join('')}</nav>`;
}
function gallery(){return `<main class="atlas" id="main"><header class="atlas-header"><div><div class="eyebrow">VPPS ONE · DESIGN ATLAS · V1.0</div><h1>A calmer school day.</h1><p>Different responsibilities. One familiar design language. Explore ${catalog.length} responsive screens, built around the next useful action for each person.</p></div><div>${link('components','Explore design system','','apps','admin')}</div></header><div class="note" style="margin-bottom:28px"><strong>Interactive reference, not the live application</strong>Every name and amount is illustrative. Resize a view to compare phone and desktop layouts. The accountant screens describe the original School Fees workspace; they do not introduce a new financial engine into VPPS One.</div><div class="atlas-grid">${catalog.map(([id,h,p,r],i)=>`<article class="atlas-card"><a href="${url(id,r)}"><img src="screenshots/${id}-desktop.png" alt="${h} desktop design" loading="lazy"></a><div><div class="eyebrow">${String(i+1).padStart(2,'0')} / ${r.toUpperCase()}</div><h2 style="margin-top:8px">${h}</h2><p>${p}</p><div class="actions">${link(id,'Explore view','primary','arrow',r)}<a class="button" href="screenshots/${id}-mobile.png">Phone image</a></div></div></article>`).join('')}</div><p class="footer-note">Start with README.md and HANDOFF.md for implementation guidance. No build tools or remote assets are required to view this atlas.</p></main>`}
document.documentElement.lang=hi?'hi':'en';
document.title=screen==='gallery'?'VPPS One — design atlas':`${catalog.find(x=>x[0]===screen)[1]} — VPPS One design`;
document.querySelector('#app').innerHTML=screen==='gallery'?gallery():['request-link','login'].includes(screen)?renderers[screen]():shell(renderers[screen]());

let feedbackTimer;
function toast(message){const e=document.querySelector('#feedback');e.textContent=message;e.classList.add('visible');clearTimeout(feedbackTimer);feedbackTimer=setTimeout(()=>e.classList.remove('visible'),4000)}
function modal(h,p){document.querySelector('#dialog-content').replaceChildren();const title=document.createElement('h2');title.id='dialog-title';title.textContent=h;const text=document.createElement('p');text.textContent=p;document.querySelector('#dialog-content').append(title,text);document.querySelector('#dialog').showModal()}
function attendanceCounts(){const counts={P:0,A:0,L:0,E:0};document.querySelectorAll('.att[aria-pressed=true]').forEach(e=>counts[e.dataset.value]++);document.querySelector('#attendance-counts').innerHTML=Object.entries(counts).map(([k,n])=>mini({P:'Present',A:'Absent',L:'Late',E:'Excused'}[k],String(n))).join('');return counts}
document.addEventListener('click',event=>{
 const att=event.target.closest('.att');if(att){att.closest('[data-attendance]').querySelectorAll('.att').forEach(b=>b.setAttribute('aria-pressed',String(b===att)));attendanceCounts();document.querySelector('#save-state').textContent='Unsaved changes · check counts before saving';return}
 const day=event.target.closest('[data-day]');if(day){document.querySelectorAll('[data-day]').forEach(b=>b.classList.toggle('active',b===day));document.querySelector('#day-agenda').innerHTML=day.dataset.day==='1'?timeline(true):`<div class="time-row"><span class="time">09:10</span><div class="time-content current"><h3>English · ${day.dataset.day==='0'?'VI B':'VII A'}</h3><p>Period 2 · Room 14</p></div></div><div class="time-row"><span class="time">11:10</span><div class="time-content"><h3>English · VIII A</h3><p>Period 4 · Room 18</p></div></div>`;return}
 const action=event.target.closest('[data-action]')?.dataset.action;if(!action)return;
 if(action==='all-present'){document.querySelectorAll('.att').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.value==='P')));attendanceCounts();document.querySelector('#save-state').textContent='Unsaved changes · 4 students marked present';return}
 if(action==='save-attendance'){const c=attendanceCounts();document.querySelector('#save-state').textContent=`Saved in this preview · ${c.P} present · ${c.A} absent · ${c.L} late · ${c.E} excused`;toast('Attendance saved in this preview. Reload resets the example.');return}
 if(action==='confirm-contact'){document.querySelector('#request-status').textContent='Confirmed in this preview. 6 of 8 checked.';return}
 if(action==='correct-contact'){const v=document.querySelector('#corrected-contact').value.trim();if(!/^[\d\s+()-]{10,18}$/.test(v)){modal('Check the number','Enter a complete phone number before sending a correction.');return}document.querySelector('#request-status').textContent='Correction received in this preview. Waiting for office review.';return}
 if(action==='approve'||action==='reject'){if(action==='reject'&&!document.querySelector('#review-note').value.trim()){modal('Add a reason','Explain why this correction is being rejected so the teacher knows what to fix.');return}document.querySelector('#review-state').textContent=action==='approve'?'Approved in this preview · the change is ready to apply.':'Rejected in this preview · reason recorded.';document.querySelectorAll('[data-action=approve],[data-action=reject]').forEach(b=>b.disabled=true);return}
 if(action==='preview-audience'){const selected=document.querySelector('input[name=audience]:checked');modal('Audience preview',`Selected: ${selected.closest('label').querySelector('strong').textContent}. ${document.querySelector('#audience-count').textContent}. This preview creates no links and sends no messages.`);return}
 if(action==='save-preferences'){const lang=document.querySelector('#language-choice').value;if(lang==='हिंदी'&&role==='teacher'){location.href=url('teacher-hi','teacher');return}modal('Preference preview',`${lang} selected. The complete Hindi reference is the teacher home. Production preferences must stay with the signed-in account.`);return}
 const dialogs={
  export:['Export preview','The production export must use the same filters and include the same number of rows as the list. No file or student data is exported by this design.'],
  print:['Print preview','Use the browser print command to inspect the print stylesheet. This design does not issue a real receipt.'],
  'receipt-share':['Receipt message preview','Payment of ₹4,200 received for Aarav Sharma. Receipt #1286. This example sends no message.'],
  'payment-correction':['Review correction','Show the original payment, proposed correction, reason and resulting balance before confirming.'],
  'report-period':['Period preview','The selected dates define the report period. Production results and exports must agree on date boundaries.'],
  'assign-kavita':['Cover assigned · preview','Kavita Rao · English, VII B · Period 4. Production assignment rechecks availability before saving.'],
  'assign-ravi':['Cover assigned · preview','Ravi Mehta · English, VII B · Period 4. Production assignment rechecks availability before saving.'],
  publish:['Ready to publish?','Class VI A · Unit Test 2. All required marks and attendance must pass review. This preview does not publish a report.'],
  'batch-upload':['Batch upload preview','Preview each filename beside the matched student. Keep ambiguous and unmatched rows separate before committing the batch.'],
  'add-photo':['Add student photograph','The production sheet offers Take photo and Choose file, followed by crop, preview, replace and upload progress. No camera is opened in this preview.'],
  'staff-preview':['Staff management','Search accounts, inspect assigned classes and confirm each role change. This view uses the existing staff management workflow.'],
  'session-preview':['Academic session','Current session: 2026–27. Show the impact on enrolments, calendars and reports before changing a school-wide setting.'],
  'jobs-preview':['Background jobs','Show the last run, its outcome, affected record count and a retry action for failed work.'],
  'activity-preview':['Activity history','Show actor, time, affected record, old value, new value and reason with searchable filters.'],
  'retry-save':['Retry complete · preview','The same draft is retried. A production retry must not create a duplicate submission.'],
  conflict:['Compare latest information','Show the latest approved value beside your proposed change. Require a fresh review before replacing it.'],
  notifications:['You’re up to date','Your task inbox is the primary place for work. Notifications link to a specific actionable item.'],
  'demo-save':['Saved · preview','The save state appears after the server has acknowledged the change.'],
  'demo-cancel':['Cancelled · preview','An actual form must retain or discard its draft according to the documented interaction.'],
  'demo-delete':['Confirm removal','Name the affected item and consequence. Destructive controls are kept away from routine saves.']
 };if(dialogs[action])modal(...dialogs[action]);
});
document.querySelector('#payment-form')?.addEventListener('submit',event=>{event.preventDefault();const amount=Number(document.querySelector('#amount').value);if(!Number.isFinite(amount)||amount<=0){document.querySelector('#payment-error').textContent='Enter an amount greater than zero.';return}modal('Review payment',`Aarav Sharma · SR 02401. Receive ${new Intl.NumberFormat('en-IN',{style:'currency',currency:'INR'}).format(amount)} by ${document.querySelector('#mode').value}. This is a design preview; no payment is recorded.`)});
document.querySelector('#amount')?.addEventListener('input',event=>{const n=Number(event.target.value);document.querySelector('#receiving').textContent=Number.isFinite(n)?new Intl.NumberFormat('en-IN',{style:'currency',currency:'INR',maximumFractionDigits:2}).format(n):'—'});
document.querySelector('#student-search')?.addEventListener('input',event=>{const term=event.target.value.toLowerCase().trim();let count=0;document.querySelectorAll('[data-student]').forEach(row=>{row.hidden=!row.dataset.student.includes(term);if(!row.hidden)count++});document.querySelector('#no-matches').hidden=count>0});
document.querySelectorAll('input[name=audience]').forEach(input=>input.addEventListener('change',()=>{const counts={class:'32',gaps:'8',route:'18',custom:'12'};const n=counts[input.value];document.querySelector('#audience-count').textContent=`${n} children`;document.querySelector('#audience-expected').textContent=n;document.querySelector('#audience-description').textContent=input.closest('label').querySelector('p').textContent}));
document.querySelectorAll('.absent-check').forEach(input=>input.addEventListener('change',()=>{const mark=input.closest('tr').querySelector('.mark-input');mark.disabled=input.checked;if(input.checked)mark.value=''}));
document.querySelector('#marks-form')?.addEventListener('submit',event=>{event.preventDefault();const rows=[...document.querySelectorAll('#marks-form tbody tr')];const absent=rows.filter(r=>r.querySelector('.absent-check').checked).length;const entered=rows.filter(r=>!r.querySelector('.absent-check').checked&&r.querySelector('.mark-input').value!=='').length;document.querySelector('#marks-state').textContent=`Saved in preview · ${entered} scored · ${absent} absent · ${rows.length-entered-absent} remaining`;toast('Marks saved in this preview. Blank entries remain incomplete.')});
document.querySelector('#login-form')?.addEventListener('submit',event=>{event.preventDefault();document.querySelector('#login-state').textContent='Preview only — credentials were not sent. The real sign-in opens the account’s assigned workspace.'});
